import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
const root = new URL('../src/docs/', import.meta.url);
const docs = { 'agents-start-here': readFileSync(new URL('agents-start-here.md', root), 'utf8') };
for (const file of readdirSync(new URL('topics/', root)).sort()) {
  if (file.endsWith('.md'))
    docs[file.slice(0, -3)] = readFileSync(new URL('topics/' + file, root), 'utf8');
}
const content =
  '// Generated by scripts/bundle-docs.mjs. Edit src/docs/*.md or topics/*.md.\n' +
  'export const DOCS: Readonly<Record<string, string>> = ' +
  JSON.stringify(docs, null, 2) +
  ';\n';
writeFileSync(new URL('../src/docs/bundled.ts', import.meta.url), content);
